import { api, setCsrf, invalidateRequests } from './api.js';
import { icon } from './icons.js';
const $ = (s, el=document) => el.querySelector(s);
const esc = (v='') => String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const today = () => new Date(Date.now()-new Date().getTimezoneOffset()*60000).toISOString().slice(0,10);
const num = v => v == null ? '—' : esc(v);
const initials = s => (s||'').split(' ').slice(0,2).map(x=>x[0]).join('');
const roleNames = {admin:'Administrator',head:'Institution head',trainer:'Trainer'};
const pageNames = {overview:'Overview',institutions:'Institutions',classes:'Classrooms',attendance:'My attendance',trainers:'Trainers',reviews:'Review queue',reports:'Daily report',evaluation:'Accuracy lab',deployment:'System & cameras',privacy:'Privacy & evidence'};
let state={institutions:[],trainers:[],classes:[],activity:[]}, user=null, page='overview', caps={}, evaluationList=[], devices=[], incoming=[], search='', filter='all', reportDate=today(), selected=null, authMode='login', refreshing=false;let sessionEpoch=0;
const inst = id => state.institutions.find(i=>i.id===id);
const trainer = id => state.trainers.find(t=>t.id===id);
const needsReview = c => ['review','unverified'].includes(c.status) && c.review?.decision !== 'accepted';
const canManage = () => ['head','admin'].includes(user?.role);
const qualityMessages = {
  count_variation: 'Sampled headcounts vary. Review the range and sampled frames before accepting the estimate.',
  posture_uncertain: 'Some postures are uncertain. New uncertain candidates are excluded; a still-visible person may use recently confirmed seated history for up to 30 seconds.',
  short_observation: 'The available recording is shorter than the requested observation. The result covers only the footage actually read.',
  temporal_warmup: 'More observations are needed to confirm stable seated presence.',
  insufficient_seated_evidence: 'There is not enough clear evidence to establish seated attendance.',
  temporal_count_variation: 'The supported seated count changes over the observation. Review the time series and count range.',
  brief_occlusion_recovered: 'Recently confirmed seated presence was supported through a brief missing detection of at most 3 seconds.',
  insufficient_temporal_evidence: 'Too few observations support a stable seated attendance count.',
  unstable_seated_count: 'Seated presence changes too much to establish a reliable attendance count.',
  posture_coverage_low: 'Too few visible people have reliable posture evidence; review is required.',
  insufficient_visible_evidence: 'Too little visible evidence supports the proposed seated count.',
  ambiguous_spatial_reassociation: 'Overlapping or moving detections could not be matched confidently by position; review is required.',
  posture_from_recent_history: 'A visible person at a stable position uses seated posture confirmed within the last 30 seconds. Standing detections are excluded immediately.',
  sparse_observation: 'Samples are too far apart to confirm continuous presence or bridge missed detections reliably.',
  camera_motion: 'Camera movement weakens position-based presence support; review the observation.',
  unstable_headcount: 'The headcount varies across sampled frames. A reliable attendance count could not be established.',
  insufficient_usable_frames: 'Too few usable frames were captured to establish a reliable count.',
  incomplete_observation: 'Some video frames could not be read. The observation is incomplete.',
  low_resolution: 'The image resolution is too low for a reliable check.',
  dark_frame: 'Some frames are too dark to inspect reliably.',
  overexposed_frame: 'Some frames are too bright to inspect reliably.',
  blurred_frame: 'Blur obscures people or equipment in some frames.',
  frozen_frames: 'Repeated frames suggest a frozen feed; continued presence cannot be verified.',
  single_image_only: 'This observation uses one image and cannot verify continued presence.',
  no_people_detected_not_proof_of_empty_room: 'No people were detected. This does not prove the classroom is empty.',
  invalid_model_output: 'The detector produced an invalid observation; review the source and retry.',
  detector_limit: 'The detector reached its object limit; the observation may be incomplete.'
};
const qualityMessage = flag => qualityMessages[flag] || String(flag).replaceAll('_',' ').replace(/^./,c=>c.toUpperCase());
const observationMode = () => 'all_people';
const modeLabel = () => 'all visible people';
function durationLabel(seconds) {
  if(seconds==null || !Number.isFinite(Number(seconds)))return 'unavailable';
  const value=Math.round(Math.max(0,Number(seconds))*10)/10, minutes=Math.floor(value/60), remaining=Number((value%60).toFixed(1));
  return minutes?`${minutes} min${remaining?` ${remaining} sec`:''}`:`${Number(value.toFixed(1))} sec`;
}
function countingFields(c={}) {
  return '';
}
function observationWindowSummary(c) {
  const analysis=c.analysis, window=analysis?.observationWindow;
  const target=window?.requestedSeconds;
  if(!window)return '';
  return `<section class="notice observation-window">${icon('clock')}<div><strong>${window.complete?'Observation window complete':'Partial observation window'}</strong><p>${esc(durationLabel(window.observedSeconds))}${target!=null?` observed / ${esc(durationLabel(target))} requested`:''}${window.sourceDuration!=null?` · Source length: ${esc(durationLabel(window.sourceDuration))}`:''}${window.sampleIntervalSeconds!=null?` · Sampling interval: ${esc(durationLabel(window.sampleIntervalSeconds))}`:''}.</p>${window.complete?'':'<p>The estimate applies only to the available observation; missing time is not reconstructed.</p>'}</div></section>`;
}
function analysisProgress(c) {
  if(!['processing','analyzing'].includes(c.status))return '';
  const job=c.activeJob, raw=Number(job?.progress), available=job?.progress!=null&&Number.isFinite(raw);
  const progress=Math.min(1,Math.max(0,raw)), percent=available?Math.round(progress*100):null;
  return `<section id="analysis-progress" class="notice"><span class="spinner"></span><div style="width:100%"><strong>${job?.status==='queued'?'Verification queued':'Analysis in progress'}${percent!=null?` · ${percent}%`:''}</strong><p>${esc(job?.message||'Analysis continues on the monitoring server.')}</p>${available?`<progress aria-label="Analysis progress" value="${progress}" max="1" style="width:100%">${percent}%</progress>`:''}<p>Live cameras need the configured observation time. This view updates automatically.</p>${c.analysis?'<p>The counts and evidence shown here are from the previous completed observation until this check finishes.</p>':''}</div></section>`;
}
function updateAnalysisProgress(c) {
  const container=$('#analysis-progress');
  if(container&&c&&['processing','analyzing'].includes(c.status))container.outerHTML=analysisProgress(c);
}
function frameObservations(a) {
  return table(['Time (seconds)','Visible people','Visibility'],a.frames.map(f=>`<tr><td>${num(f.time??f.timeSeconds)}</td><td>${num(f.people)}</td><td>${esc(f.qualityFlags?.length?f.qualityFlags.map(qualityMessage).join(' '):f.usable===false?'Unusable sample':'Clear sample')}</td></tr>`));
}
function countInfo(c) {
  const a=c.analysis||{}, uncertain=a.confidence==='low' || (a.count===null && a.candidateCount!=null);
  const range=Array.isArray(a.countRange)?a.countRange:[a.countRange?.min,a.countRange?.max];
  const rangeText=range.length===2&&range.every(v=>v!=null)?`${range[0]}–${range[1]}`:'';
  return {uncertain, count:uncertain?null:c.observedCount, candidate:a.candidateCount??(uncertain?c.observedCount:null), rangeText};
}
function countCell(c) {
  const value=countInfo(c);
  return `${num(value.count)}${value.uncertain?`<p class="cell-subtitle wrap-note">Uncertain estimate${value.candidate!=null?`: ${num(value.candidate)}`:''}${value.rangeText?`<br>Sample range: ${esc(value.rangeText)}`:''}</p>`:''}`;
}
function observationEvidence(a) {
  const entries=a?.evidence?.filter(e=>e.url)||[];
  return entries.map(entry=>{
    const frame=Number.isInteger(entry.frameIndex)?a.frames?.[entry.frameIndex]:a.frames?.find(f=>Math.abs((f.time??f.timeSeconds)-entry.time)<0.001);
    return {...entry,time:entry.time??frame?.time??frame?.timeSeconds,people:entry.people??frame?.people};
  });
}
function evidenceCaption(entry,index) {
  const time=entry.time==null?'Timestamp unavailable':`${Number(entry.time).toFixed(2)} seconds`;
  return `Sample ${Number.isInteger(entry.frameIndex)?entry.frameIndex+1:index+1} · ${time}${entry.people!=null?` · ${entry.people} detected people`:''}`;
}
const isSnapshot = entry => entry?.privacy==='source_pixels_retained' || entry?.type==='annotated_snapshot';
const evidenceAlt = (entry,index=0) => `${isSnapshot(entry)?'Camera snapshot with numbered person boxes':'Abstract classroom diagram; original pixels removed'}: ${entry?evidenceCaption(entry,index):'Classroom observation'}`;
const evidenceDescription = (entry,index=0) => `${evidenceCaption(entry,index)}. Person numbers apply only to this snapshot. This frame’s count may differ from the overall estimate.`;
function updateEvidencePreview(index) {
  const c=state.classes.find(x=>x.id===selected), entries=observationEvidence(c?.analysis), entry=entries[Number(index)];
  if(!entry)return;
  const image=$('#observation-evidence-image'), caption=$('#observation-evidence-caption');
  if(image){image.src=entry.url;image.alt=evidenceAlt(entry,Number(index));}
  if(caption)caption.textContent=evidenceDescription(entry,Number(index));
  const title=$('#observation-evidence-title');
  if(title)title.textContent=isSnapshot(entry)?'Camera snapshot':'Observation diagram';
}

const menu = () => user.role==='trainer' ? ['overview','attendance','classes','privacy'] : user.role==='head' ? ['overview','classes','trainers','reviews','reports','deployment','privacy'] : ['overview','institutions','classes','reviews','reports','evaluation','deployment','privacy'];
function toast(message,error=false) { const el=document.createElement('div'); el.className=`toast ${error?'error':''}`; el.setAttribute('role','status'); el.innerHTML=`${icon(error?'alert':'check')}<span>${esc(message)}</span>`; $('#toast-root').append(el); setTimeout(()=>el.remove(),7000); }
function badge(status) { const label={verified:'Counts aligned',review:'Needs review',pending:'Awaiting attendance',unverified:'Unable to verify',processing:'Analyzing',analyzing:'Analyzing',reviewed:'Reviewed',queued:'Queued',running:'Running',completed:'Complete',failed:'Failed',present:'Observed',gap:'Possible gap',unknown:'Not verifiable'};return `<span class="badge ${['gap','failed'].includes(status)?'review':status}">${esc(label[status]||status||'Pending')}</span>`; }
function btn(label,action,id='',kind='primary',ico='plus') {return `<button class="button ${kind}" data-action="${action}" data-id="${esc(id)}">${icon(ico)}${label}</button>`;}
function heading(kicker,title,desc,actions='') {return `<section class="page-heading"><div><p class="eyebrow">${esc(kicker)}</p><h1>${title}</h1><p class="page-description">${desc}</p></div><div class="heading-actions">${actions}</div></section>`;}
function card(title,subtitle,body,action='') {return `<section class="card"><header class="card-header"><div><h2 class="card-title">${title}</h2><p class="card-subtitle">${subtitle}</p></div>${action}</header><div class="card-body">${body}</div></section>`;}
function empty(title,desc,action='') {return `<div class="empty-state">${icon('classes')}<h3>${title}</h3><p>${desc}</p>${action}</div>`;}
function stat(label,value,note,ico='classes') {return `<article class="stat-card"><div class="stat-top"><span class="stat-label">${label}</span><span class="stat-icon">${icon(ico)}</span></div><strong class="stat-value">${value}</strong><p class="stat-foot">${note}</p></article>`;}
function field(label,name,type='text',value='',extra='',full=false) {return `<label class="form-field ${full?'full-width':''}"><span>${label}</span><input class="form-input" name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;}
function select(label,name,options,extra='') {return `<label class="form-field"><span>${label}</span><select class="form-input" name="${name}" ${extra}>${options}</select></label>`;}
const option = (v,t,sel=false)=>`<option value="${esc(v)}" ${sel?'selected':''}>${esc(t)}</option>`;
const note = text=>`<div class="notice">${icon('info')}<div>${text}</div></div>`;
function table(headers,rows) {return `<div class="table-wrap"><table class="data-table"><thead><tr>${headers.map(x=>`<th scope="col">${x}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table></div>`;}
function showModal(title,subtitle,body,wide=false) {closeModal();$('#modal-root').innerHTML=`<dialog aria-labelledby="modal-title" class="modal ${wide?'wide':''}"><header class="modal-header"><div><h2 id="modal-title">${title}</h2><p>${subtitle}</p></div><button class="modal-close" data-action="close" aria-label="Close dialog">${icon('close')}</button></header>${body}</dialog>`;const d=$('dialog');d.showModal();d.addEventListener('close',()=>{if($('#modal-root dialog')===d){selected=null;$('#modal-root').innerHTML='';}},{once:true});}
function closeModal(){ const d=$('dialog');if(d)d.close();selected=null;$('#modal-root').innerHTML=''; }
function formModal(title,subtitle,id,body,submit='Save',wide=false){showModal(title,subtitle,`<form id="${id}"><div class="modal-body"><div class="form-grid">${body}</div><p class="form-error" role="alert"></p></div><footer class="modal-footer"><button type="button" class="button secondary" data-action="close">Cancel</button><button class="button primary" type="submit">${submit}</button></footer></form>`,wide);}
function renderAuth(mode='login',message='') {sessionEpoch++;invalidateRequests();closeModal();authMode=mode;user=null;state={institutions:[],trainers:[],classes:[],activity:[]};devices=[];evaluationList=[];caps={};incoming=[];page='overview';$('#app').innerHTML=`<main class="auth-layout" id="main-content"><section class="auth-story"><a class="brand" href="/"><span class="brand-mark">${icon('scan')}</span><span class="brand-text">CentreWatch<span>Training assurance</span></span></a><p class="eyebrow">EVERY CLASSROOM, ACCOUNTED FOR</p><h1>Confidence starts<br>with a clear picture.</h1><p>One workspace for attendance, infrastructure, and the people responsible for every training centre.</p><div class="auth-orbit"><div class="orbit-ring"></div><div class="orbit-ring inner"></div><span class="orbit-centre">${icon('shield')}</span><span class="orbit-chip chip-one">${icon('people')} Aggregate presence</span><span class="orbit-chip chip-two">${icon('building')} Infrastructure checks</span><span class="orbit-chip chip-three">${icon('check')} Accountable review</span></div><small>Local video processing · Role-based access · Recorded decisions</small></section><section class="auth-panel"><div class="auth-box"><span class="badge verified">${mode==='setup'?'FIRST-TIME SETUP':'SECURE WORKSPACE'}</span><h2>${mode==='setup'?'Set up your workspace':'Welcome back.'}</h2><p>${mode==='setup'?'Create the administrator account. You can then add institutions and their heads.':'Sign in to your assigned workspace.'}</p><form id="auth-form">${mode==='setup'?field('Full name','name','text','','required autocomplete="name"'):''}${field('Email address','email','email','','required autocomplete="username"')}${field('Password','password','password','','required '+(mode==='setup'?'minlength="10" autocomplete="new-password"':'autocomplete="current-password"'))}<p class="form-error" role="alert">${esc(message)}</p><button class="button primary" type="submit">${mode==='setup'?'Create workspace':'Sign in'} ${icon('arrow')}</button></form><p class="auth-help">${mode==='setup'?'Use at least 10 characters for your password.':'Your administrator or institution head creates your account.'}</p></div></section></main>`;}
async function refresh(renderPage=true){if(refreshing)return;refreshing=true;const epoch=sessionEpoch;try{const data=await api('/bootstrap');if(epoch!==sessionEpoch)return;if(data.setupRequired){renderAuth('setup');return;}state={institutions:[],trainers:[],classes:[],activity:[],...data};user=data.user;authMode='login';devices=data.devices||[];evaluationList=data.evaluationReports||[];setCsrf(data.csrfToken);if(!user){renderAuth();return;}if(renderPage)render();}catch(e){if(epoch!==sessionEpoch)return;if(e.status===401)renderAuth();else if(!user)$('#app').innerHTML=empty('Server unavailable',esc(e.message),btn('Try again','refresh','','primary','clock'));else toast(e.message,true);}finally{refreshing=false;}}
async function navigate(next){if(!menu().includes(next))return;page=next;search='';filter='all';document.body.classList.remove('nav-open');history.replaceState(null,'',`#${page}`);render();if(['deployment','evaluation'].includes(page))await loadExtra();}
async function loadExtra(){const epoch=sessionEpoch;const activePage=page;const results=await Promise.allSettled([api('/capabilities'),...(page==='evaluation'?[api('/evaluations')]:[api('/devices')])]);if(epoch!==sessionEpoch||activePage!==page)return;if(results[0].status==='fulfilled')caps=results[0].value;if(results[1]?.status==='fulfilled'){const v=results[1].value;if(page==='evaluation')evaluationList=Array.isArray(v)?v:v.evaluations||v.reports||[];else devices=Array.isArray(v)?v:v.devices||[];}else if(results[1])toast(results[1].reason.message,true);render();}
function render(){if(!user)return;const reviews=state.classes.filter(needsReview).length;const nav=menu();if(!nav.includes(page))page='overview';$('#app').innerHTML=`<div class="app-shell"><button class="mobile-overlay" data-action="close-nav" aria-label="Close navigation"></button><aside class="sidebar"><a class="brand" href="#overview" data-page="overview"><span class="brand-mark">${icon('scan')}</span><span class="brand-text">CentreWatch<span>Training assurance</span></span></a><div class="workspace-card"><span class="workspace-symbol">${icon('building')}</span><div><span class="workspace-title">${user.role==='admin'?'National workspace':esc(inst(user.institutionId)?.name||'Training centre')}</span><span class="workspace-caption">${roleNames[user.role]}</span></div><span class="workspace-dot"></span></div><div class="nav-section-label">WORKSPACE</div><nav class="nav-list">${nav.map(n=>`<a href="#${n}" data-page="${n}" class="nav-item ${page===n?'active':''}" ${page===n?'aria-current="page"':''}><span class="nav-icon">${icon({institutions:'building',trainers:'people',attendance:'people',reviews:'shield',reports:'report',evaluation:'scan',deployment:'camera',privacy:'shield'}[n]||n)}</span>${pageNames[n]}${n==='reviews'&&reviews?`<span class="nav-count">${reviews}</span>`:''}</a>`).join('')}</nav><div class="sidebar-bottom"><div class="sidebar-help"><span class="help-orbit">${icon('shield')}</span><strong>Clarity in every count.</strong><p>Review the evidence.<br>Keep the human decision.</p></div><div class="user-card"><span class="avatar">${esc(initials(user.name))}</span><div><strong>${esc(user.name)}</strong><small>${roleNames[user.role]}</small></div><button class="icon-button" data-action="change-password" aria-label="Change password">${icon('shield')}</button></div></div></aside><div class="main-shell"><header class="topbar"><div class="breadcrumb"><button class="icon-button mobile-menu-button" data-action="open-nav" aria-label="Open navigation">${icon('menu')}</button><span>Workspace</span><span>/</span><strong>${pageNames[page]}</strong></div><div class="topbar-actions"><span class="connection-indicator"><i></i> Local monitoring</span><button class="icon-button" data-action="refresh" aria-label="Refresh records">${icon('clock')}</button><button class="icon-button ${reviews?'has-dot':''}" data-page="${canManage()?'reviews':'classes'}" aria-label="View attention items">${icon('bell')}</button><span class="avatar">${esc(initials(user.name))}</span><button type="button" class="button secondary logout-button" data-action="logout" title="Sign out to use another account">${icon('logout')}<span>Logout</span></button></div></header><main id="main-content" class="page-content" tabindex="-1">${content()}</main><footer class="app-footer"><span>CentreWatch · Every classroom, accounted for.</span><span>${icon('shield')} Aggregate counts. Human review.</span></footer></div></div>`;}
function content(){return ({overview,classes:classPage,attendance:classPage,institutions:institutionPage,trainers:trainerPage,reviews:reviewPage,reports:reportPage,evaluation:evaluationPage,deployment:deploymentPage,privacy:privacyPage}[page]||overview)();}
function overview(){const all=state.classes,items=all.filter(c=>c.date===today()),reviews=all.filter(needsReview),finished=items.filter(c=>countInfo(c).count!=null),gaps=all.filter(c=>c.analysis?.equipment?.some(e=>e.status==='gap'));const action=user.role==='admin'?btn('Add institution','new-institution'):user.role==='head'?btn('Create class','new-class'):btn('Mark attendance','attendance-page','','primary','people');return heading('YOUR MONITORING WORKSPACE',user.role==='admin'?'Every centre. One clear picture.':`Your ${user.role==='head'?'centre':'day'}, at a glance.`,`Attendance, infrastructure, and the checks that need your attention.`,action)+`<div class="stats-grid">${stat('Classes today',items.length,`${all.length} scheduled sessions`)}${stat('Attendance checked',finished.length,`${items.filter(c=>c.submittedCount!=null).length} submitted`,'people')}${stat('Needs attention',reviews.length,'Awaiting a human decision','alert')}${stat('Infrastructure flags',gaps.length,'Visible equipment gaps','building')}</div><div class="dashboard-grid">${card('The verification loop','From a trainer’s count to a recorded decision',`<ol class="workflow-steps"><li><span>01</span><div><strong>Connect a classroom</strong><p>Upload footage or connect the room’s camera.</p></div></li><li><span>02</span><div><strong>Submit & verify</strong><p>Attendance triggers local visual analysis.</p></div></li><li><span>03</span><div><strong>Review the difference</strong><p>Inspect counts, visibility, and equipment flags.</p></div></li></ol>`)}${card('Recent activity','A traceable record of submissions and decisions',state.activity.length?`<ul class="activity-list">${state.activity.slice(0,5).map(a=>`<li class="activity-item"><span class="activity-dot ${a.type==='review'?'review':''}">${icon('check')}</span><div class="activity-content"><strong>${esc(a.message)}</strong><p>${new Date(a.time).toLocaleString('en-IN')}</p></div></li>`).join('')}</ul>`:empty('Your workspace is ready','New submissions and reviews will appear here.'))}</div>${card(reviews.length?'Attention needed':'Today’s classrooms',reviews.length?'Investigate discrepancies and visibility constraints.':'Your scheduled training sessions.',classTable(reviews.length?reviews.slice(0,6):items.slice(0,6)))}`;}
function classTable(items){if(!items.length)return empty('No classes here yet',user.role==='head'?'Add a trainer, then create a class with its footage.':'Classes appear here when your institution schedules them.');return table(['Classroom','Institution / trainer','Reported','Observed','Status',''],items.map(c=>`<tr><td><strong class="cell-title">${esc(c.name)}</strong><p class="cell-subtitle">${esc(c.room)} · ${esc(c.date)} · ${esc(c.startTime)}</p></td><td>${esc(inst(c.institutionId)?.name||'')}<p class="cell-subtitle">${esc(trainer(c.trainerId)?.name||'')}</p></td><td class="count-value">${num(c.submittedCount)}</td><td class="count-value">${countCell(c)}</td><td>${badge(c.status)}</td><td>${btn(c.submittedCount==null&&user.role==='trainer'?'Mark attendance':'View details',c.submittedCount==null&&user.role==='trainer'?'attendance':'detail',c.id,'secondary','arrow')}</td></tr>`));}
function classPage(){let items=state.classes.filter(c=>(filter==='all'||c.status===filter)&&`${c.name} ${c.room} ${inst(c.institutionId)?.name||''}`.toLowerCase().includes(search.toLowerCase()));return heading('CLASSROOM OPERATIONS',page==='attendance'?'Make every session count.':'Classrooms, connected.','Each session brings together its trainer, inventory, and camera source.',user.role==='head'?btn('Create class','new-class'):'')+`<div class="toolbar"><label class="search-field">${icon('search')}<input id="search" aria-label="Search classes" placeholder="Search classroom or institution" value="${esc(search)}"></label><select id="status-filter" class="filter-select" aria-label="Filter by status">${[['all','All statuses'],['pending','Awaiting attendance'],['review','Needs review'],['verified','Counts aligned'],['analyzing','Analyzing'],['unverified','Unable to verify']].map(([v,t])=>option(v,t,filter===v)).join('')}</select></div><div class="card">${classTable(items)}</div>`;}
function institutionPage(){return heading('NETWORK MANAGEMENT','A stronger network, together.','Create an institution and its accountable head in one step.',btn('Add institution','new-institution'))+`<div class="institution-grid">${state.institutions.map(i=>card(esc(i.name),`${esc(i.code)} · ${esc(i.city)}`,`<div class="institution-head">${icon('people')} ${esc(i.head)}<p class="text-muted">${esc(i.email)}</p></div><div class="detail-counts"><div class="count-box"><span>Classes</span><strong>${state.classes.filter(c=>c.institutionId===i.id).length}</strong></div><div class="count-box"><span>Review queue</span><strong>${state.classes.filter(c=>c.institutionId===i.id&&needsReview(c)).length}</strong></div></div>`)).join('')||`<div class="card">${empty('Start with your first institution','Create its institution head account to begin scheduling classes.',btn('Add institution','new-institution'))}</div>`}</div>`;}
function trainerPage(){return heading('YOUR TEACHING TEAM','People behind the progress.','Institution accounts with access to their assigned sessions.',btn('Add trainer','new-trainer'))+`<div class="card">${state.trainers.length?table(['Trainer','Specialty','Assigned classes'],state.trainers.map(t=>`<tr><td><strong class="cell-title">${esc(t.name)}</strong><p class="cell-subtitle">${esc(t.email)}</p></td><td>${esc(t.specialty||'—')}</td><td>${state.classes.filter(c=>c.trainerId===t.id).length}</td></tr>`)):empty('Build your training team','Add a trainer before creating a class.')}</div>`;}
function reviewPage(){return heading('COMPLIANCE FOLLOW-UP','A flag is the start of a review.','Inspect attendance differences, equipment observations, and visibility constraints.')+`<div class="card">${classTable(state.classes.filter(needsReview))}</div>`;}
function reportPage(){const rows=state.classes.filter(c=>c.date===reportDate);return heading('DAILY ASSURANCE','The whole day, accounted for.','Every institution and class, with both reported and observed counts.',`<a class="button secondary" href="/api/reports.csv?date=${reportDate}">${icon('download')} Export CSV</a>`)+`<div class="toolbar"><label class="date-picker">Report date <input class="form-input" id="report-date" type="date" value="${reportDate}"></label></div><div class="stats-grid">${stat('Institutions',new Set(rows.map(c=>c.institutionId)).size,'With sessions on this date','building')}${stat('Classes',rows.length,'Scheduled sessions')}${stat('Reported total',rows.reduce((n,c)=>n+(c.submittedCount||0),0),'Sum of submitted attendance','people')}${stat('Observed subtotal',rows.reduce((n,c)=>n+(countInfo(c).count||0),0),`${rows.filter(c=>countInfo(c).count==null).length} sessions without a reliable count`,'scan')}</div><div class="card">${classTable(rows)}</div>`;}
function evaluationPage(){return heading('MEASURE WHAT MATTERS','Evidence before confidence.','Compare predictions against independently annotated footage.',btn('Run evaluation','new-evaluation','','primary','scan'))+note('Metrics appear only after an evaluation has run on labelled footage. Count errors, alert errors, and object-detection errors are reported separately.')+`<div class="dashboard-grid">${card('Prepare your dataset','Use the footage intake folder and a ground-truth manifest',`<ol class="plain-list"><li>Place clips in <code>centre-watch/data/incoming/</code>.</li><li>Record true headcounts at selected timestamps.</li><li>Record visible inventory and the sanctioned quantities.</li><li>Use separate development and test rooms or cameras.</li></ol><a class="button secondary" href="/api/evaluations/example">${icon('download')} Download manifest template</a>`)}${card('What the report measures','No invented accuracy percentages',`<ul class="plain-list"><li>Count MAE / RMSE and overcounts / undercounts.</li><li>Attendance and inventory alert false positives / negatives.</li><li>Abstentions and evaluation coverage.</li><li>Object precision / recall only with labelled boxes.</li></ul>`)}</div><div class="card">${evaluationList.length?table(['Evaluation','Status','Created',''],evaluationList.map(e=>`<tr><td>${esc(e.name||e.id)}</td><td>${badge(e.status)}</td><td>${esc(e.createdAt||e.created_at||'')}</td><td>${btn('View report','evaluation-detail',e.id,'secondary','report')}</td></tr>`)):empty('No completed assessments yet','Add your annotated clips, then run the evaluation.')}</div>`;}
function deploymentPage(){const v=caps.vision||caps.model||caps;const ready=v.seatedReady??(v.ready===true||v.available===true||caps.modelReady===true);return heading('DEPLOYMENT & CONNECTIVITY','Designed for the centre.','Local analysis continues when the centre loses its internet connection.',(user.role==='admin'?btn('Assign footage','assign-footage','','secondary','video')+btn('Retention settings','settings','','secondary','clock'):'')+btn('Register sync device','new-device','','secondary','plus'))+`<div class="stats-grid">${stat('Inference engine',ready?'Ready':'Not ready',esc(v.model||v.name||'Check local model preparation'),'scan')}${stat('Scheduled monitoring',state.classes.filter(c=>c.monitoringEnabled).length,'Only during configured session hours','clock')}${stat('Registered devices',devices.length,'Institution-scoped credentials','camera')}${stat('Raw-video sync','Off','Only aggregate observations leave the centre','shield')}</div><div class="dashboard-grid">${card('Camera sources','A source belongs to a scheduled classroom',`<p>Create a class with an uploaded photo/video, an incoming file, or an RTSP stream. RTSP credentials are kept on the server.</p><p class="text-muted spaced">Use a fixed, calibrated classroom view. A low-confidence result is sent for review. Uploaded clips are recordings, and repeat checks do not turn them into live coverage.</p>${note('Automatic pan/tilt scanning is not enabled. Moving between views can count the same person twice. A fixed view or calibrated camera coverage is required for reliable attendance.')}`)}${card('Low-bandwidth operation','Inference runs beside the camera',`<ul class="plain-list"><li>Models are prepared once, then loaded locally.</li><li>Disconnected observations queue in a durable outbox.</li><li>Reconnect to send compact, idempotent JSON events.</li><li>Raw footage stays on the centre’s machine.</li></ul><p class="text-muted">Deployment instructions: <code>docs/LOW_BANDWIDTH_DEPLOYMENT.md</code></p>`)}</div>${card('Device registry','Keys are shown once when a device is registered.',devices.length?table(['Device','Institution','Last seen',''],devices.map(d=>`<tr><td>${esc(d.name)}</td><td>${esc(inst(d.institutionId)?.name||'')}</td><td>${esc(d.lastSeenAt||d.lastSeen||'Not synced yet')}</td><td>${d.revoked?badge('Revoked'):btn('Revoke','revoke-device',d.id,'secondary','close')}</td></tr>`)):empty('No sync devices registered','Register a device to connect a centre’s outbox to this monitoring server.'))}<details class="diagnostics"><summary>Technical readiness</summary><pre>${esc(JSON.stringify(caps,null,2))}</pre></details>`;}
function privacyPage(){return heading('RESPONSIBLE MONITORING','Presence, without a name.','Understand what the system observes and what its evidence can establish.')+`<div class="dashboard-grid">${card('What is measured','Aggregate compliance signals',`<ul class="plain-list"><li>Confirmed seated people by default, or all visible people when configured.</li><li>Standing and uncertain postures, with uncertainty sent for review.</li><li>Presence supported across the actual observation duration.</li><li>Visible inventory items and their quantities.</li><li>Image-quality and coverage constraints.</li><li>Differences from submitted attendance and sanctioned inventory.</li></ul>`)}${card('What is not inferred','Privacy and interpretation boundaries',`<ul class="plain-list"><li>No face identification or biometric templates.</li><li>No mapping from a person’s appearance or posture to a trainee name or trainer role.</li><li>No claim that a matching count proves individual attendance.</li><li>No claim that a stationary machine is broken.</li></ul>`)}</div>${card('Evidence & retention','Access is checked for every request',`<p>Analysis runs locally. Temporary position tracks can support a missing detection for at most 3 seconds. A still-visible person at a stable position may use seated posture confirmed within 30 seconds; standing detections are excluded immediately. These tracks are not identities and do not link people across cameras or sessions. Camera snapshots show actual sampled footage; people may be recognizable. Seated mode boxes only confirmed seated detections, but standing people can remain visible in the original image. Person numbers are local to each snapshot and are never matched to trainee names. Snapshot and source access is restricted by institution and assigned class. Older observations may contain diagrams with the original pixels removed. Uploaded media and generated evidence expire after their configured retention periods; files you place in the intake folder remain under your control. The low-bandwidth edge client sends counts and status metadata only.</p><p class="spaced">Submitted counts, observed counts, and human review notes are kept separately. Review decisions never rewrite the original observation.</p><p class="text-muted spaced">Full design note: <code>docs/PRIVACY_DESIGN.md</code></p>`)}`;}
async function newClass(){const result=await api('/incoming');incoming=Array.isArray(result)?result:result.files||[];if(!state.trainers.length)throw new Error('Add a trainer first, then create the class.');formModal('Create a classroom session','Upload or select the footage before creating the class.','class-form',field('Class name','name','text','','required')+field('Course / trade','course')+field('Room','room','text','','required')+select('Assigned trainer','trainerId',state.trainers.map(t=>option(t.id,t.name)).join(''),'required')+field('Session date','date','date',today(),'required')+field('Seating capacity','capacity','number',30,'required min="1" max="1000"')+field('Start time','startTime','time','09:00','required')+field('End time','endTime','time','17:00','required')+`<label class="form-field full-width"><span>Sanctioned inventory · one item and quantity per line</span><textarea class="form-input" name="inventory" rows="3" placeholder="chair: 30&#10;workbench: 4"></textarea><small>Equipment outside the prepared model vocabulary is marked unverified.</small></label>`+select('Footage source','source',option('upload','Upload a video or photo')+option('incoming','Choose from intake folder')+option('rtsp','Connect an RTSP camera'))+`<div></div><label class="form-field full-width source-upload"><span>Video or photo · maximum 512 MB</span><input class="form-input" name="media" type="file" accept="video/mp4,video/quicktime,video/x-msvideo,video/x-matroska,video/webm,image/jpeg,image/png"></label><label class="form-field full-width source-incoming" hidden><span>Incoming footage</span><select class="form-input" name="incomingFile"><option value="">Select a file</option>${incoming.map(f=>option(typeof f==='string'?f:f.name,typeof f==='string'?f:f.name)).join('')}</select></label><label class="form-field full-width source-rtsp" hidden><span>RTSP camera URL</span><input class="form-input" name="rtspUrl" type="password" autocomplete="off" placeholder="rtsp://camera-address/stream"></label>`+countingFields()+field('Count tolerance','tolerance','number',state.settings?.tolerance??0,'min="0" max="20"')+field('Check interval (minutes)','intervalMinutes','number',state.settings?.intervalMinutes||30,'min="5" max="120"')+`<label class="form-field full-width source-rtsp" hidden><span><input type="checkbox" name="monitoringEnabled"> Repeat checks during the session’s scheduled hours</span><small>Scheduled checks use this live camera during the class’s hours, with timing jitter.</small></label><label class="form-field full-width"><span><input type="checkbox" name="coverageConfirmed"> I have confirmed the camera covers the full sanctioned inventory area</span><small>Without this confirmation, equipment absence is marked unverified.</small></label><details class="full-width"><summary>Trainee seating region (optional)</summary><p class="text-muted">Normalized [left, top, right, bottom] coordinates let you exclude the trainer’s area. Example: [0,0.2,1,1].</p><textarea class="form-input" name="traineeZone" rows="2" placeholder="[0,0.2,1,1]"></textarea></details>`,'Create class',true);}
function detail(id){const c=state.classes.find(x=>x.id===id);if(!c)return;const a=c.analysis;const eq=a?.equipment||[];const counts=countInfo(c);const mode=observationMode(c);const evidenceEntries=observationEvidence(a);const evidence=evidenceEntries[0]?.url||a?.evidenceUrl||c.evidenceUrl;showModal(esc(c.name),`${esc(c.room)} · ${esc(c.date)} · ${esc(c.startTime)}–${esc(c.endTime)}`,`<div class="modal-body"><div class="detail-topline">${badge(c.status)}<span>${esc(inst(c.institutionId)?.name||'')} · ${esc(trainer(c.trainerId)?.name||'')}</span></div><div class="detail-counts"><div class="count-box"><span>Reported</span><strong>${num(c.submittedCount)}</strong></div><div class="count-box"><span>${counts.uncertain?'Reliable observed count':mode==='seated_only'?'Observed seated':'Observed'}</span><strong>${num(counts.count)}</strong>${counts.uncertain&&counts.candidate!=null?`<small>Uncertain estimate: ${num(counts.candidate)}</small>`:''}</div><div class="count-box"><span>Difference</span><strong>${counts.count==null||c.submittedCount==null?'—':Math.abs(counts.count-c.submittedCount)}</strong></div></div>${counts.rangeText?`<p class="text-muted spaced">${mode==='seated_only'?'Supported seated count':'Sampled headcounts'}: ${esc(counts.rangeText)} people.${counts.uncertain?' A reliable count and attendance difference are unavailable.':''}</p>`:''}${observationWindowSummary(c)}${a?.qualityFlags?.length?note(a.qualityFlags.map(flag=>esc(qualityMessage(flag))).join('<br>')):''}${a?.detail?note(esc(a.detail)):''}${c.sourceExpired?note('The uploaded source expired under the retention policy. Counts and review records are preserved.'):''}${analysisProgress(c)}${a?`<p class="text-muted">Evidence quality: ${esc(a.confidence||'unavailable')} (not an accuracy score) · ${esc(a.frames?.length||0)} sampled frames · ${esc(a.model||a.source||'Local analysis')}</p>`:''}${evidence?`<section class="spaced"><h3 id="observation-evidence-title" class="section-title">${isSnapshot(evidenceEntries[0])?'Camera snapshot':'Observation diagram'}</h3>${evidenceEntries.length?`<label class="form-field"><span>Choose a sampled frame</span><select id="evidence-frame" class="form-input">${evidenceEntries.map((entry,index)=>option(index,evidenceCaption(entry,index),index===0)).join('')}</select></label><p id="observation-evidence-caption" class="text-muted spaced">${esc(evidenceDescription(evidenceEntries[0],0))}</p>`:''}<img id="observation-evidence-image" class="evidence-image observation-snapshot" src="${esc(evidence)}" alt="${esc(evidenceAlt(evidenceEntries[0]))}"></section>`:''}<h3 class="section-title">Infrastructure observations</h3>${eq.length?table(['Equipment','Expected','Observed','Finding'],eq.map(e=>`<tr><td>${esc(e.name)}</td><td>${num(e.expected)}</td><td>${num(e.observed)}</td><td>${badge(e.status)}<p class="cell-subtitle wrap-note">${esc(e.reason||'')}</p><p class="cell-subtitle">Operability: ${esc(e.operability||'unverified')}</p></td></tr>`)):note(c.expectedEquipment?.length?'Inventory is recorded. Observations appear after analysis.':'No sanctioned inventory was entered for this session.')}<p class="text-muted spaced">${esc(a?.observationScope||(mode==='seated_only'?'Only confirmed seated people in the configured area contribute to attendance; standing people are excluded.':'The count includes every visible person in the selected area.'))} ${mode==='seated_only'?'A seated trainer can count and a standing student can be excluded. A missing detection may be supported for at most 3 seconds. A still-visible, spatially stable person may use seated posture confirmed within 30 seconds; standing is excluded immediately. New arrivals are not accumulated into a total. ':''}Counts do not identify trainees. Image quality, occlusion, and people outside the frame can affect the result.</p>${c.review?`<section class="review-note"><strong>Recorded decision · ${esc(c.review.decision)}</strong><p>${esc(c.review.note)}</p><small>${esc(c.review.time||c.review.createdAt||'')}</small></section>`:''}${a?.frames?.length?`<details class="diagnostics"><summary>Frame-by-frame observations</summary>${frameObservations(a)}</details>`:''}${canManage()&&needsReview(c)?`<form id="review-form" data-id="${esc(c.id)}" class="review-form spaced"><label class="form-field"><span>Review note</span><textarea class="form-input" name="note" required minlength="3" rows="3" placeholder="Document the explanation or the follow-up required."></textarea></label><div class="inline-actions"><button class="button secondary" name="decision" value="followup">Request follow-up</button><button class="button primary" name="decision" value="accepted">Accept with note</button></div><p class="form-error" role="alert"></p></form>`:''}</div><footer class="modal-footer">${canManage()?btn('Configure','edit-class',c.id,'secondary','camera')+btn('Replace source','replace-source',c.id,'secondary','upload'):''}${btn('History','history',c.id,'secondary','clock')}${canManage()&&c.media.source!=='rtsp'&&!c.sourceExpired?btn('Inspect footage','source-preview',c.id,'secondary','video'):''}${user.role==='trainer'?btn(c.submittedCount==null?'Mark attendance':'Update attendance','attendance',c.id,'secondary','people'):''}${c.submittedCount!=null&&!['processing','analyzing'].includes(c.status)?btn('Run verification','analyze',c.id,'primary','scan'):''}<button class="button secondary" data-action="close">Close</button></footer>`,true);selected=c.id;}
function attendance(id){const c=state.classes.find(x=>x.id===id);formModal('Mark attendance',`${esc(c.name)} · ${esc(c.room)}`,'attendance-form',`<input type="hidden" name="classId" value="${esc(id)}">`+field('Number of trainees present','submittedCount','number',c.submittedCount??'','required min="0" max="1000"',true)+`<label class="form-field full-width"><span>Session note (optional)</span><textarea class="form-input" name="note" rows="3"></textarea></label>`,'Submit & verify');}
function newInstitution(){formModal('Add institution','Create the institution and its head’s account.','institution-form',field('Institution name','name','text','','required')+field('Institution code','code','text','','required')+field('City / district','city','text','','required')+field('Institution head','head','text','','required')+field('Head’s email','email','email','','required')+field('Initial password','password','password','','required minlength="10" autocomplete="new-password"'),'Create institution');}
function newTrainer(){formModal('Add trainer','The trainer can submit attendance for assigned classes.','trainer-form',field('Full name','name','text','','required')+field('Specialty / trade','specialty')+field('Email address','email','email','','required')+field('Initial password','password','password','','required minlength="10" autocomplete="new-password"'),'Create trainer');}
async function evaluationDetail(id){const result=await api(`/evaluations/${encodeURIComponent(id)}`);const r=result.report,m=r?.metrics,c=m?.count,a=m?.attendance_alerts;const confusion=(label,v)=>`<tr><td>${esc(label)}</td><td>${num(v.tp)}</td><td>${num(v.fp)}</td><td>${num(v.fn)}</td><td>${num(v.tn)}</td><td>${num((v.unverified_positive||0)+(v.unverified_negative||0)+(v.unknown_ground_truth||0))}</td></tr>`;showModal('Dataset assessment',esc(result.name||id),`<div class="modal-body">${badge(result.status)}${result.message?note(esc(result.message)):''}${r?`<div class="stats-grid spaced">${stat('Count MAE',num(c.countMAE),'People per scored observation','people')}${stat('Count RMSE',num(c.countRMSE),'Larger errors weigh more','scan')}${stat('Scored frames',c.scored_observations,`${c.total_observations} labelled observations`)}${stat('Abstained',r.coverage.abstained_or_missing,'Not counted as correct','alert')}</div><h3 class="section-title">Snapshot discrepancy alerts</h3>${table(['Check','True +','False +','False −','True −','Unverified'],[confusion('Attendance',a),...Object.entries(m.infrastructure_alerts).map(([n,v])=>confusion(n,v))])}<h3 class="section-title">Object detection</h3>${m.object_detection.available?table(['Object','True detections','False detections','Missed objects'],Object.entries(m.object_detection.classes).map(([n,v])=>`<tr><td>${esc(n)}</td><td>${v.tp}</td><td>${v.fp}</td><td>${v.fn}</td></tr>`)):note('Object-level false positives and false negatives require exhaustive bounding-box annotations.')}<ul class="plain-list spaced">${r.limitations.map(t=>`<li>${esc(t)}</li>`).join('')}</ul>`:note('This report updates when evaluation finishes.')}<details class="diagnostics"><summary>Complete assessment JSON</summary><pre class="json-report">${esc(JSON.stringify(r||result,null,2))}</pre></details></div><footer class="modal-footer">${r?`<a class="button secondary" href="/api/evaluations/${encodeURIComponent(id)}/artifacts/report.json">Download JSON</a><a class="button primary" href="/api/evaluations/${encodeURIComponent(id)}/artifacts/predictions.csv">Download predictions CSV</a>`:''}<button class="button secondary" data-action="close">Close</button></footer>`,true);}
async function replaceSource(id){const c=state.classes.find(c=>c.id===id);const result=await api('/incoming');const files=(result.files||[]).filter(f=>!f.institutionId||f.institutionId===c.institutionId);formModal('Replace classroom source','Previous observations remain in history. Re-run verification after replacing the source; enable any live schedule in Configure.','replace-form',`<input type="hidden" name="classId" value="${esc(id)}">`+select('Footage source','source',option('upload','Upload video or photo')+option('incoming','Assigned incoming file')+option('rtsp','RTSP camera'))+`<div></div><label class="form-field full-width source-upload"><span>Replacement media · maximum 512 MB</span><input class="form-input" type="file" name="media" accept="video/mp4,video/webm,video/quicktime,video/x-msvideo,video/x-matroska,image/jpeg,image/png"></label><label class="form-field full-width source-incoming" hidden><span>Incoming footage</span><select name="incomingFile" class="form-input"><option value="">Select a file</option>${files.map(f=>option(f.name,f.name)).join('')}</select></label><label class="form-field full-width source-rtsp" hidden><span>RTSP URL</span><input class="form-input" type="password" name="rtspUrl" autocomplete="off"></label>`,'Replace source');}
function sourcePreview(id){const c=state.classes.find(c=>c.id===id);const url=`/api/media/${encodeURIComponent(c.media.id)}`;showModal('Source footage',`${esc(c.name)} · Restricted to authorized reviewers in this workspace`, `<div class="modal-body">${note('Original footage and annotated snapshots may show recognizable people. Access is restricted to authorized users for this class. Person numbers identify detections within a snapshot; they are not trainee identities.')}${c.media.type.startsWith('image/')?`<img class="evidence-image" src="${url}" alt="Original source submitted for this class">`:`<video class="evidence-image" controls preload="metadata" src="${url}"></video>`}</div><footer class="modal-footer">${btn('Back to observation','detail',id,'secondary','arrow')}</footer>`,true);}
function editClass(id){const c=state.classes.find(c=>c.id===id);formModal('Configure session','Changing the configuration preserves previous observations and starts a new verification revision.','configure-form',`<input type="hidden" name="classId" value="${esc(id)}">`+field('Class name','name','text',c.name,'required')+field('Room','room','text',c.room,'required')+select('Trainer','trainerId',state.trainers.filter(t=>t.institutionId===c.institutionId).map(t=>option(t.id,t.name,t.id===c.trainerId)).join(''))+field('Capacity','capacity','number',c.capacity,'min="1" max="1000" required')+field('Session date','date','date',c.date,'required')+field('Count tolerance','tolerance','number',c.tolerance,'min="0" max="20"')+field('Start time','startTime','time',c.startTime,'required')+field('End time','endTime','time',c.endTime,'required')+countingFields(c)+field('Check interval (minutes)','intervalMinutes','number',c.intervalMinutes,'min="5" max="120"')+field('Trainee zone [left,top,right,bottom]','traineeZone','text',c.traineeZone?JSON.stringify(c.traineeZone):'')+`<label class="form-field full-width"><span><input name="monitoringEnabled" type="checkbox" ${c.monitoringEnabled?'checked':''} ${c.media.source!=='rtsp'?'disabled':''}> Monitor this live camera during session hours</span></label><label class="form-field full-width"><span><input name="coverageConfirmed" type="checkbox" ${c.coverageConfirmed?'checked':''}> Full inventory area is visible</span></label>`,'Save configuration',true);}
async function observationHistory(id){const data=await api(`/classes/${id}/observations`);showModal('Observation history','Each verification is preserved with its original submitted count.',`<div class="modal-body">${data.observations.length?table(['Captured','Submitted','Observed','Status'],data.observations.map(o=>`<tr><td>${esc(new Date(o.capturedAt).toLocaleString('en-IN'))}</td><td>${num(o.submittedCount)}</td><td>${countCell(o)}</td><td>${badge(o.status||'Historical')}</td></tr>`)):empty('No observations yet','Submit attendance to run the first check.')}</div>`,true);}
async function assignFootage(){const data=await api('/incoming');formModal('Assign incoming footage','Only the assigned institution can attach this source to its classes.','assign-form',select('Incoming file','filename',(data.files||[]).map(f=>option(f.name,`${f.name}${f.institutionId?' · assigned':''}`)).join(''),'required')+select('Institution','institutionId',state.institutions.map(i=>option(i.id,i.name)).join(''),'required'),'Assign footage');}
function systemSettings(){const s=state.settings||{};formModal('Retention & default settings','These settings apply to uploaded sources and generated diagrams. Incoming originals are never automatically deleted.','settings-form',field('Uploaded media retention (hours)','uploadRetentionHours','number',s.uploadRetentionHours||24,'min="1" max="720" required')+field('Evidence retention (days)','retentionDays','number',s.retentionDays||30,'min="1" max="365" required')+field('Default check interval (minutes)','intervalMinutes','number',s.intervalMinutes||30,'min="5" max="120" required')+field('Default count tolerance','tolerance','number',s.tolerance??0,'min="0" max="20" required'),'Save settings');}
function changePassword(){formModal('Change your password','Use at least 10 characters. Other sessions will be signed out.','password-form',field('Current password','currentPassword','password','','required autocomplete="current-password"',true)+field('New password','password','password','','required minlength="10" autocomplete="new-password"',true),'Update password');}
async function revokeDevice(id){await api(`/devices/${id}`,{method:'DELETE'});await loadExtra();toast('Device credential revoked.');}
const handlers={
'source-preview':sourcePreview,'replace-source':replaceSource,
'edit-class':editClass,'history':observationHistory,'assign-footage':assignFootage,'settings':systemSettings,'change-password':changePassword,'revoke-device':revokeDevice,refresh:()=>refresh(),logout:async()=>{await api('/logout',{method:'POST'});setCsrf('');closeModal();renderAuth('login');},'open-nav':()=>document.body.classList.add('nav-open'),'close-nav':()=>document.body.classList.remove('nav-open'),close:closeModal,'attendance-page':()=>navigate('attendance'),'new-institution':newInstitution,'new-trainer':newTrainer,'new-class':newClass,detail,attendance,analyze:async(id)=>{await api(`/classes/${id}/analyze`,{method:'POST'});await refresh();detail(id);toast('Verification queued on the monitoring server.');},'new-evaluation':()=>formModal('Run a dataset evaluation','Use independently labelled timestamps. The selected files must exist in the intake folder.','evaluation-form',field('Evaluation name','name','text','','required',true)+`<label class="form-field full-width"><span>Ground-truth manifest (.json)</span><input type="file" name="manifest" accept="application/json,.json" required class="form-input"></label>`,'Run evaluation'),'evaluation-detail':evaluationDetail,'new-device':()=>formModal('Register a sync device','This device can submit aggregate observations for one institution.','device-form',field('Device name','name','text','','required')+(user.role==='admin'?select('Institution','institutionId',state.institutions.map(i=>option(i.id,i.name)).join(''),'required'):''),'Register device')};
document.addEventListener('click',async e=>{const p=e.target.closest('[data-page]');if(p){e.preventDefault();await navigate(p.dataset.page);return;}const b=e.target.closest('[data-action]');if(!b)return;e.preventDefault();try{await handlers[b.dataset.action]?.(b.dataset.id);}catch(err){toast(err.message,true);}});
document.addEventListener('input',e=>{if(e.target.id==='search'){search=e.target.value;const cursor=e.target.selectionStart;render();$('#search')?.focus();$('#search')?.setSelectionRange(cursor,cursor);}});
document.addEventListener('change',e=>{if(e.target.id==='evidence-frame'){updateEvidencePreview(e.target.value);return;}if(e.target.id==='status-filter'){filter=e.target.value;render();}if(e.target.id==='report-date'){reportDate=e.target.value;render();}if(e.target.name==='source'){for(const n of ['upload','incoming','rtsp'])document.querySelectorAll(`.source-${n}`).forEach(el=>el.hidden=n!==e.target.value);if(e.target.value!=='rtsp'&&$('input[name=monitoringEnabled]'))$('input[name=monitoringEnabled]').checked=false;}});
document.addEventListener('submit',async e=>{e.preventDefault();const f=e.target;if(!f.id)return;const values=Object.fromEntries(new FormData(f));const error=$('.form-error',f);if(error)error.textContent='';const buttons=[...f.querySelectorAll('button[type="submit"],button:not([type])')];const old=buttons.map(b=>b.textContent);buttons.forEach(b=>{b.disabled=true;b.textContent='Working…';});try{
if(f.id==='auth-form'){await api(authMode==='setup'?'/setup':'/login',{method:'POST',body:values});await refresh();return;}
if(f.id==='institution-form')await api('/institutions',{method:'POST',body:values});
if(f.id==='replace-form'){const body={monitoringEnabled:false};if(values.source==='upload'){const file=f.elements.media.files[0];if(!file)throw new Error('Choose the replacement video or photo.');const data=new FormData();data.append('file',file);const media=await api('/media',{method:'POST',body:data});body.mediaId=media.id;}else if(values.source==='incoming'){if(!values.incomingFile)throw new Error('Select an assigned incoming file.');body.incomingFile=values.incomingFile;}else{body.rtspUrl=values.rtspUrl;}await api(`/classes/${values.classId}`,{method:'PATCH',body});}
if(f.id==='settings-form')await api('/settings',{method:'PATCH',body:Object.fromEntries(Object.entries(values).map(([k,v])=>[k,Number(v)]))});
if(f.id==='password-form')await api('/account/password',{method:'POST',body:values});
if(f.id==='assign-form')await api('/incoming/assign',{method:'POST',body:values});
if(f.id==='configure-form'){const {classId,...body}=values;body.capacity=Number(body.capacity);body.intervalMinutes=Number(body.intervalMinutes);body.tolerance=Number(body.tolerance);body.monitoringEnabled=body.monitoringEnabled==='on';body.coverageConfirmed=body.coverageConfirmed==='on';body.traineeZone=body.traineeZone.trim()?JSON.parse(body.traineeZone):null;await api(`/classes/${classId}`,{method:'PATCH',body});}
if(f.id==='trainer-form')await api('/trainers',{method:'POST',body:values});
if(f.id==='class-form'){
 const payload={name:values.name,course:values.course,room:values.room,trainerId:values.trainerId,date:values.date,startTime:values.startTime,endTime:values.endTime,capacity:Number(values.capacity),tolerance:Number(values.tolerance),intervalMinutes:Number(values.intervalMinutes),monitoringEnabled:values.monitoringEnabled==='on',coverageConfirmed:values.coverageConfirmed==='on',expectedEquipment:[]};
 for(const line of values.inventory.split('\n').map(x=>x.trim()).filter(Boolean)){const m=line.match(/^(.+?)\s*:\s*(\d+)$/);if(!m)throw new Error('Enter inventory as item: quantity, one item per line.');payload.expectedEquipment.push({name:m[1].trim(),quantity:Number(m[2]),observable:values.coverageConfirmed==='on'});}
 if(values.traineeZone.trim())payload.traineeZone=JSON.parse(values.traineeZone);
 if(values.source==='upload'){const file=f.elements.media.files[0];if(!file)throw new Error('Choose a video or photo first.');if(file.size>512*1024*1024)throw new Error('The upload limit is 512 MB. Put larger files in the intake folder.');const form=new FormData();form.append('file',file);const media=await api('/media',{method:'POST',body:form});payload.mediaId=media.id;}
 else if(values.source==='incoming'){if(!values.incomingFile)throw new Error('Select a file from the intake folder.');payload.incomingFile=values.incomingFile;}
 else {if(!values.rtspUrl)throw new Error('Enter the camera’s RTSP URL.');payload.rtspUrl=values.rtspUrl;}
 await api('/classes',{method:'POST',body:payload});
}
if(f.id==='attendance-form'){await api(`/classes/${values.classId}/attendance`,{method:'POST',body:{submittedCount:Number(values.submittedCount),note:values.note}});closeModal();await refresh();detail(values.classId);toast('Attendance saved. Verification is running.');return;}
if(f.id==='review-form'){await api(`/classes/${f.dataset.id}/review`,{method:'POST',body:{note:values.note,decision:e.submitter?.value||'followup'}});}
if(f.id==='evaluation-form'){const manifest=JSON.parse(await f.elements.manifest.files[0].text());await api('/evaluations',{method:'POST',body:{name:values.name,manifest}});closeModal();await loadExtra();toast('Dataset evaluation queued.');return;}
if(f.id==='device-form'){const r=await api('/devices',{method:'POST',body:values});showModal('Device registered','Save this key now. It is only shown once.',`<div class="modal-body">${note('Use this credential only on the registered centre’s device.')}<label class="form-field"><span>Device ID</span><input class="form-input" readonly value="${esc(r.id)}"></label><label class="form-field spaced"><span>Device key</span><textarea class="form-input" readonly rows="3">${esc(r.key||r.deviceKey||r.token||'')}</textarea></label></div><footer class="modal-footer"><button class="button primary" data-action="close">Done</button></footer>`);await loadExtra();return;}
closeModal();await refresh();toast('Saved successfully.');
}catch(err){if(error&&error.isConnected)error.textContent=err.message;else toast(err.message,true);}finally{buttons.forEach((b,i)=>{b.disabled=false;b.textContent=old[i];});}});
setInterval(async()=>{if(!user||document.hidden)return;const hasJob=state.classes.some(c=>['processing','analyzing'].includes(c.status));if(hasJob||page==='reviews'||page==='overview'){const id=selected;const wasAnalyzing=['analyzing','processing'].includes(state.classes.find(c=>c.id===id)?.status);await refresh(!$('#modal-root dialog'));if(id&&wasAnalyzing&&$('dialog')){const current=state.classes.find(c=>c.id===id);if(current&&['analyzing','processing'].includes(current.status))updateAnalysisProgress(current);else if(current)detail(id);}}if(page==='evaluation'&&evaluationList.some(e=>['queued','running'].includes(e.status)))await loadExtra();},5000);
window.addEventListener('online',()=>{if(user)refresh();});
await refresh();
if(user){const initial=location.hash.slice(1);if(menu().includes(initial))await navigate(initial);api('/capabilities').then(x=>{caps=x;}).catch(()=>{});}
